import React, { createContext, useContext } from "react";
import { Audio, Sequence, staticFile } from "remotion";

// Sound effects live in public/sfx/<name>.wav (generated by scripts/gen_sfx.py, or drop in your own).
// Components place them declaratively next to the animation they belong to: <Sfx name="pop" at={cue} />
export const SFX = {
  whoosh: 20,
  swish: 10,
  swipe: 8,
  impact: 30,
  pop: 8,
  click: 5,
  tick: 4,
  ding: 40,
  riser: 50,
  glitch: 12,
  typing: 40,
  bubbles: 45,
  sparkle: 30,
  success: 30,
  stamp: 14,
} as const;
export type SfxName = keyof typeof SFX;

const SfxCtx = createContext(true);
export const SfxProvider: React.FC<{ enabled: boolean; children: React.ReactNode }> = ({ enabled, children }) => <SfxCtx.Provider value={enabled}>{children}</SfxCtx.Provider>;

export const Sfx: React.FC<{ name: SfxName; at: number; volume?: number }> = ({ name, at, volume = 0.35 }) => {
  const on = useContext(SfxCtx);
  if (!on || !Number.isFinite(at) || at < 0) return null;
  return (
    <Sequence from={Math.round(at)} durationInFrames={SFX[name] + 6} name={`sfx:${name}`} layout="none">
      <Audio src={staticFile(`sfx/${name}.wav`)} volume={volume} />
    </Sequence>
  );
};
